static int evaluatePostfix(String[] tokens) {
  Deque<Integer> stack = new ArrayDeque<>();
  for (String token : tokens) {
    if (token.matches("\\d+")) stack.push(Integer.parseInt(token));
    else {
      int b = stack.pop();
      int a = stack.pop();
      if (token.equals("+")) stack.push(a + b);
      else if (token.equals("-")) stack.push(a - b);
      else if (token.equals("*")) stack.push(a * b);
      else stack.push(a / b);
    }
  }
  return stack.pop();
}

