static String minWindow(String text, String target) {
  Map<Character, Integer> need = new HashMap<>();
  for (char c : target.toCharArray())
    need.put(c, need.getOrDefault(c, 0) + 1);
  Map<Character, Integer> have = new HashMap<>();
  int left = 0, formed = 0, best = Integer.MAX_VALUE, start = 0;
  for (int right = 0; right < text.length(); right++) {
    char c = text.charAt(right);
    have.put(c, have.getOrDefault(c, 0) + 1);
    if (need.containsKey(c) && have.get(c).intValue() == need.get(c)) formed++;
    while (formed == need.size()) {
      if (right - left + 1 < best) {
        best = right - left + 1;
        start = left;
      }
      char drop = text.charAt(left++);
      have.put(drop, have.get(drop) - 1);
      if (need.containsKey(drop) && have.get(drop) < need.get(drop)) formed--;
    }
  }
  return best == Integer.MAX_VALUE ? "" : text.substring(start, start + best);
}

