    prefix *= nums[i];
  }
  int suffix = 1;
  for (int i = nums.length - 1; i >= 0; i--) {
    result[i] *= suffix;
    suffix *= nums[i];
  }
  return result;
}

static int maxProduct(int[] nums) {
  int max = nums[0], min = nums[0], best = nums[0];
  for (int i = 1; i < nums.length; i++) {
    if (nums[i] < 0) {
      int temp = max;
      max = min;
      min = temp;
    }
    max = Math.max(nums[i], max * nums[i]);
    min = Math.min(nums[i], min * nums[i]);
    best = Math.max(best, max);
  }
  return best;
}

static int coinChange(int[] coins, int amount) {
  int[] dp = new int[amount + 1];
  Arrays.fill(dp, amount + 1);
  dp[0] = 0;
  for (int current = 1; current <= amount; current++) {
    for (int coin : coins) {
      if (coin <= current)
        dp[current] = Math.min(dp[current], dp[current - coin] + 1);
    }
  }
  return dp[amount] > amount ? -1 : dp[amount];
}

static int lis(int[] nums) {
  if (nums.length == 0) return 0;
  int[] dp = new int[nums.length];
  Arrays.fill(dp, 1);
  int best = 1;
  for (int i = 1; i < nums.length; i++) {
    for (int j = 0; j < i; j++) {
      if (nums[i] > nums[j])
        dp[i] = Math.max(dp[i], dp[j] + 1);
    }
    best = Math.max(best, dp[i]);
  }
  return best;
}

static int rob(int[] houses) {
  int previous = 0, current = 0;
  for (int money : houses) {
    int next = Math.max(current, previous + money);
    previous = current;
    current = next;
  }
  return current;
}

static int countIslands(char[][] grid) {
  int count = 0;
  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[0].length; c++) {
      if (grid[r][c] == '1') {
        flood(grid, r, c);
        count++;
      }
    }
  }
  return count;
}

static void flood(char[][] grid, int r, int c) {
  if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length || grid[r][c] != '1') return;
  grid[r][c] = '0';
  flood(grid, r + 1, c);
  flood(grid, r - 1, c);
  flood(grid, r, c + 1);
  flood(grid, r, c - 1);
}

static boolean canFinish(int courses, int[][] prerequisites) {
  List<List<Integer>> graph = new ArrayList<>();
  int[] degree = new int[courses];
  for (int i = 0; i < courses; i++) graph.add(new ArrayList<>());
  for (int[] pair : prerequisites) {
    graph.get(pair[1]).add(pair[0]);
    degree[pair[0]]++;
  }
  Deque<Integer> queue = new ArrayDeque<>();
  for (int i = 0; i < courses; i++)
    if (degree[i] == 0) queue.offer(i);
  int completed = 0;
  while (!queue.isEmpty()) {
    int course = queue.poll();
    completed++;
    for (int next : graph.get(course)) {
      if (--degree[next] == 0) queue.offer(next);
    }
  }
  return completed == courses;
}

Node cloneGraph(Node node) {
  if (node == null) return null;
  Map<Node, Node> copies = new HashMap<>();
  return clone(node, copies);
}

Node clone(Node node, Map<Node, Node> copies) {
  if (copies.containsKey(node)) return copies.get(node);
  Node copy = new Node(node.val);
  copies.put(node, copy);
  for (Node neighbor : node.neighbors) {
    copy.neighbors.add(clone(neighbor, copies));
  }
  return copy;
}

boolean wordBreak(String s, List<String> wordDict) {
  Set<String> words = new HashSet<>(wordDict);
  boolean[] dp = new boolean[s.length() + 1];
  dp[0] = true;
  for (int end = 1; end <= s.length(); ++end) {
    for (int start = 0; start < end; ++start) {
      if (dp[start] && words.contains(s.substring(start, end))) {
        dp[end] = true;
        break;
      }
    }
  }
  return dp[s.length()];
}

int editDistance(String a, String b) {
  int m = a.length();
  int n = b.length();
  int[][] dp = new int[m + 1][n + 1];
  for (int i = 0; i <= m; ++i) dp[i][0] = i;
  for (int j = 0; j <= n; ++j) dp[0][j] = j;
  for (int i = 1; i <= m; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (a.charAt(i - 1) == b.charAt(j - 1)) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(dp[i - 1][j],
            Math.min(dp[i][j - 1], dp[i - 1][j - 1]));
      }
    }
  }
  return dp[m][n];
}

int uniquePaths(int rows, int cols) {
  int[][] dp = new int[rows][cols];
  for (int r = 0; r < rows; ++r) dp[r][0] = 1;
  for (int c = 0; c < cols; ++c) dp[0][c] = 1;
  for (int r = 1; r < rows; ++r) {
    for (int c = 1; c < cols; ++c) {
      dp[r][c] = dp[r - 1][c] + dp[r][c - 1];
    }
  }
  return dp[rows - 1][cols - 1];
}

List<List<Integer>> combinationSum(int[] candidates, int target) {
  List<List<Integer>> result = new ArrayList<>();
  backtrack(candidates, target, 0, new ArrayList<>(), result);
  return result;
}

void backtrack(int[] nums, int remain, int start,
               List<Integer> current, List<List<Integer>> result) {
  if (remain == 0) {
    result.add(new ArrayList<>(current));
    return;
  }
  for (int i = start; i < nums.length; ++i) {
    if (nums[i] > remain) continue;
    current.add(nums[i]);
    backtrack(nums, remain - nums[i], i, current, result);
    current.remove(current.size() - 1);
  }
}

List<List<Integer>> permute(int[] nums) {
  List<List<Integer>> result = new ArrayList<>();
  boolean[] used = new boolean[nums.length];
  build(nums, used, new ArrayList<>(), result);
  return result;
}

void build(int[] nums, boolean[] used,
           List<Integer> current, List<List<Integer>> result) {
  if (current.size() == nums.length) {
    result.add(new ArrayList<>(current));
    return;
  }
  for (int i = 0; i < nums.length; ++i) {
    if (used[i]) continue;
    used[i] = true;
    current.add(nums[i]);
    build(nums, used, current, result);
    current.remove(current.size() - 1);
    used[i] = false;
  }
}

List<List<Integer>> subsets(int[] nums) {
  List<List<Integer>> result = new ArrayList<>();
  buildSubsets(nums, 0, new ArrayList<>(), result);
  return result;
}

void buildSubsets(int[] nums, int index,
                  List<Integer> current,
                  List<List<Integer>> result) {
  if (index == nums.length) {
    result.add(new ArrayList<>(current));
    return;
  }
  buildSubsets(nums, index + 1, current, result);
  current.add(nums[index]);
  buildSubsets(nums, index + 1, current, result);
  current.remove(current.size() - 1);
}

int networkDelayTime(int[][] times, int n, int start) {
  List<int[]>[] graph = new ArrayList[n + 1];
  for (int i = 1; i <= n; ++i) graph[i] = new ArrayList<>();
  for (int[] edge : times) {
    graph[edge[0]].add(new int[]{edge[1], edge[2]});
  }
  int[] dist = new int[n + 1];
  Arrays.fill(dist, Integer.MAX_VALUE);
  dist[start] = 0;
  PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
  pq.offer(new int[]{start, 0});
  while (!pq.isEmpty()) {
    int[] current = pq.poll();
    int node = current[0];
    int distance = current[1];
    if (distance != dist[node]) continue;
    for (int[] edge : graph[node]) {
      int next = edge[0];
      int nextDistance = distance + edge[1];
      if (nextDistance < dist[next]) {
        dist[next] = nextDistance;
        pq.offer(new int[]{next, nextDistance});
      }
    }
  }
  int answer = 0;
  for (int i = 1; i <= n; ++i) {
    if (dist[i] == Integer.MAX_VALUE) return -1;
    answer = Math.max(answer, dist[i]);
  }
  return answer;
}

class Trie {
  private static class Node {
    Node[] children = new Node[26];
    boolean word;
  }

  private final Node root = new Node();

  void insert(String word) {
    Node current = root;
    for (char ch : word.toCharArray()) {
      int index = ch - 'a';
      if (current.children[index] == null) {
        current.children[index] = new Node();
      }
      current = current.children[index];
    }
    current.word = true;
  }

  boolean search(String word) {
    Node node = find(word);
    return node != null && node.word;
  }

  boolean startsWith(String prefix) {
    return find(prefix) != null;
  }

  private Node find(String text) {
    Node current = root;
    for (char ch : text.toCharArray()) {
      current = current.children[ch - 'a'];
      if (current == null) return null;
    }
    return current;
  }
}

int findKthLargest(int[] nums, int k) {
  PriorityQueue<Integer> heap = new PriorityQueue<>();
  for (int value : nums) {
    heap.offer(value);
    if (heap.size() > k) {
      heap.poll();
    }
  }
  return heap.peek();
}

double findMedianSortedArrays(int[] a, int[] b) {
  if (a.length > b.length) return findMedianSortedArrays(b, a);
  int total = a.length + b.length;
  int half = (total + 1) / 2;
  int low = 0, high = a.length;
  while (low <= high) {
    int i = (low + high) / 2;
    int j = half - i;
    int leftA = i == 0 ? Integer.MIN_VALUE : a[i - 1];
    int rightA = i == a.length ? Integer.MAX_VALUE : a[i];
    int leftB = j == 0 ? Integer.MIN_VALUE : b[j - 1];
    int rightB = j == b.length ? Integer.MAX_VALUE : b[j];
    if (leftA <= rightB && leftB <= rightA) {
      if (total % 2 == 1) return Math.max(leftA, leftB);
      return (Math.max(leftA, leftB) + Math.min(rightA, rightB)) / 2.0;
    }
    if (leftA > rightB) high = i - 1;
    else low = i + 1;
  }
  throw new IllegalArgumentException();
}

ListNode mergeKLists(ListNode[] lists) {
  PriorityQueue<ListNode> heap = new PriorityQueue<>(
      Comparator.comparingInt(node -> node.val));
  for (ListNode list : lists) {
    if (list != null) heap.offer(list);
  }
  ListNode dummy = new ListNode(0);
  ListNode tail = dummy;
  while (!heap.isEmpty()) {
    ListNode node = heap.poll();
    tail.next = node;
    tail = node;
    if (node.next != null) heap.offer(node.next);
  }
  return dummy.next;
}

List<List<Integer>> levelOrder(TreeNode root) {
  List<List<Integer>> result = new ArrayList<>();
  if (root == null) return result;
  Queue<TreeNode> queue = new LinkedList<>();
  queue.offer(root);
  while (!queue.isEmpty()) {
    int size = queue.size();
    List<Integer> level = new ArrayList<>();
    for (int i = 0; i < size; ++i) {
      TreeNode node = queue.poll();
      level.add(node.val);
      if (node.left != null) queue.offer(node.left);
      if (node.right != null) queue.offer(node.right);
    }
    result.add(level);
  }
  return result;
}

boolean isValidBST(TreeNode root) {
  return validate(root, Long.MIN_VALUE, Long.MAX_VALUE);
}

boolean validate(TreeNode node, long low, long high) {
  if (node == null) return true;
  if (node.val <= low || node.val >= high) return false;
  return validate(node.left, low, node.val) &&
         validate(node.right, node.val, high);
}

TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
  if (root == null || root == p || root == q) return root;
  TreeNode left = lowestCommonAncestor(root.left, p, q);
  TreeNode right = lowestCommonAncestor(root.right, p, q);
  if (left != null && right != null) return root;
  return left != null ? left : right;
}

String serialize(TreeNode root) {
  StringBuilder out = new StringBuilder();
  write(root, out);
  return out.toString();
}

void write(TreeNode node, StringBuilder out) {
  if (node == null) {
    out.append('#').append(',');
    return;
  }
  out.append(node.val).append(',');
  write(node.left, out);
  write(node.right, out);
}

TreeNode deserialize(String data) {
  Queue<String> values = new LinkedList<>(Arrays.asList(data.split(',)));
  return read(values);
}

TreeNode read(Queue<String> values) {
  String value = values.poll();
  if (value.equals('')) return null;
  TreeNode node = new TreeNode(Integer.parseInt(value));
  node.left = read(values);
  node.right = read(values);
  return node;
}

boolean exist(char[][] board, String word) {
  for (int r = 0; r < board.length; ++r) {
    for (int c = 0; c < board[0].length; ++c) {
      if (search(board, word, r, c, 0)) return true;
    }
  }
  return false;
}

boolean search(char[][] board, String word, int r, int c, int index) {
  if (index == word.length()) return true;
  if (r < 0 || r >= board.length || c < 0 || c >= board[0].length ||
      board[r][c] != word.charAt(index)) return false;
  char saved = board[r][c];
  board[r][c] = '#';
  boolean found = search(board, word, r + 1, c, index + 1) ||
                  search(board, word, r - 1, c, index + 1) ||
                  search(board, word, r, c + 1, index + 1) ||
                  search(board, word, r, c - 1, index + 1);
  board[r][c] = saved;
  return found;
}

class UnionFind {
  private final int[] parent;
  private final int[] rank;

  UnionFind(int n) {
    parent = new int[n];
    rank = new int[n];
    for (int i = 0; i < n; ++i) parent[i] = i;
  }

  int find(int x) {
    if (parent[x] != x) {
      parent[x] = find(parent[x]);
    }
    return parent[x];
  }

  void union(int a, int b) {
    int rootA = find(a);
    int rootB = find(b);
    if (rootA == rootB) return;
    if (rank[rootA] < rank[rootB]) {
      parent[rootA] = rootB;
    } else if (rank[rootA] > rank[rootB]) {
      parent[rootB] = rootA;
    } else {
      parent[rootB] = rootA;
      rank[rootA]++;
    }
  }

  boolean connected(int a, int b) {
    return find(a) == find(b);
  }
}

class LRUCache {
  private final int capacity;
  private final Map<Integer, Node> map = new HashMap<>();
  private final Node head = new Node(0, 0);
  private final Node tail = new Node(0, 0);

  LRUCache(int capacity) {
    this.capacity = capacity;
    head.next = tail;
    tail.prev = head;
  }

  int get(int key) {
    Node node = map.get(key);
    if (node == null) return -1;
    remove(node);
    addFirst(node);
    return node.value;
  }

  void put(int key, int value) {
    if (map.containsKey(key)) remove(map.get(key));
    Node node = new Node(key, value);
    map.put(key, node);
    addFirst(node);
    if (map.size() > capacity) {
      Node last = tail.prev;
      remove(last);
      map.remove(last.key);
    }
  }

  private void addFirst(Node node) {
    node.next = head.next;
    node.prev = head;
    head.next.prev = node;
    head.next = node;
  }

  private void remove(Node node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  private static class Node {
    int key, value;
    Node prev, next;
    Node(int key, int value) {
      this.key = key;
      this.value = value;
    }
  }
}

int minimumSpanningTree(int n, int[][] edges) {
  PriorityQueue<int[]> pq = new PriorityQueue<>(
      Comparator.comparingInt(edge -> edge[2]));
  for (int[] edge : edges) pq.offer(edge);
  UnionFind uf = new UnionFind(n);
  int total = 0;
  int used = 0;
  while (!pq.isEmpty() && used < n - 1) {
    int[] edge = pq.poll();
    if (uf.find(edge[0]) == uf.find(edge[1])) continue;
    uf.union(edge[0], edge[1]);
    total += edge[2];
    used++;
  }
  return used == n - 1 ? total : -1;
}
